/* Staff-only five-view review, vector PDF preview, explicit job attachment. */
(function(root){'use strict';
 const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 root.MIRStudioCotationUI={setup(api){
  const section=document.createElement('section');section.id='mir-site-cotation';section.className='mir-site-cotation';document.querySelector('.status-strip').after(section);let entry=null,buildingId='',active='front',snap=null,pdf=null,pdfURL=null,history=[],jobId='',jobs=[],pdfDocument=null,pdfLoading=null,pdfTask=null,previewPage=1,previewZoom=1;
  const $=s=>section.querySelector(s),clear=()=>{pdfTask?.cancel();pdfTask=null;if(pdfLoading){void pdfLoading.destroy().catch(()=>{});pdfLoading=null;}pdfDocument=null;if(pdfURL)URL.revokeObjectURL(pdfURL);pdfURL=null;pdf=null;snap=null;};
  async function refresh(){const latest=await MIRProjectStore.getActive();if(entry&&latest?.id===entry.id&&JSON.stringify(latest.planData.viewInventory)===JSON.stringify(entry.planData.viewInventory))return;entry=latest;if(!entry?.planData?.viewInventory){section.hidden=true;if(document.querySelector('#export-five-site'))document.querySelector('#export-five-site').hidden=true;return;}section.hidden=false;if(document.querySelector('#export-five-site'))document.querySelector('#export-five-site').hidden=false;const buildings=entry.planData.viewInventory.buildings;if(!buildings.some(b=>b.id===buildingId))buildingId=buildings.length===1?buildings[0].id:'';clear();render();}
  function state(){const inventory=entry.planData.viewInventory;return {inventory,buildingId,projectId:entry.id,projectName:entry.planData.title||'Projet MIR',materials:api.materials,settings:api.settings(),revision:Number($('#mir-site-revision').value),notes:$('#mir-site-notes').value,validated:$('#mir-site-validated').checked};}
  function render(){
   const inventory=entry.planData.viewInventory;
   section.innerHTML=`<h2>Cotation chantier · cinq vues</h2><p>Choisissez le bâtiment. Vérifiez les murs et les mesures avant de figer le PDF chantier.</p><label>Bâtiment<select id="mir-site-building"><option value="">Choisir le bâtiment</option>${inventory.buildings.map(b=>`<option value="${esc(b.id)}" ${b.id===buildingId?'selected':''}>${esc(b.name||b.id)}</option>`).join('')}</select></label><div class="mir-site-tabs" role="tablist">${MIRStudioCotation.keys.map(key=>`<button type="button" role="tab" data-site-view="${key}" aria-selected="${key===active}">${({front:'Avant',right:'Droite',back:'Arrière',left:'Gauche',soffits:'Soffites'})[key]}</button>`).join('')}</div><div id="mir-site-view"></div><div class="mir-site-meta"><label>Révision<input id="mir-site-revision" type="number" min="1" step="1" value="${history.length?Math.max(...history.map(x=>x.version))+1:1}"></label><label>Notes et réserves<textarea id="mir-site-notes" maxlength="3000"></textarea></label><label><input type="checkbox" id="mir-site-validated"> Dossier vérifié et complet</label></div><button id="mir-site-preview" type="button">Prévisualiser le PDF chantier · 5 pages</button><p id="mir-site-message" role="status"></p><div id="mir-site-pdf" hidden><div class="mir-site-pdf-tools"><button type="button" id="mir-site-previous">←</button><span id="mir-site-page-number" aria-live="polite"></span><button type="button" id="mir-site-next">→</button><button type="button" id="mir-site-zoom-out" aria-label="Réduire le PDF">−</button><button type="button" id="mir-site-zoom-in" aria-label="Agrandir le PDF">＋</button></div><div id="mir-site-pdf-frame" role="document" aria-label="Aperçu privé du PDF chantier"><canvas id="mir-site-pdf-canvas"></canvas></div><a id="mir-site-download" download="MIR-chantier.pdf">Télécharger les cinq pages</a></div><details id="mir-site-job"><summary>Rattacher à une job TEST</summary><p>La job et ses droits sont vérifiés par le serveur. Les anciennes versions restent disponibles.</p><a href="chantier.html?recette=1" target="_blank" rel="noopener">Ouvrir l’espace chantier TEST</a><button id="mir-site-jobs-load" type="button">Charger mes jobs autorisées</button><select id="mir-site-job-select"><option value="">Choisir une job</option>${jobs.map(j=>`<option value="${esc(j.id)}" ${j.id===jobId?'selected':''}>${esc(j.name)}</option>`).join('')}</select><button id="mir-site-attach" type="button" disabled>Rattacher ce PDF</button><div id="mir-site-history"></div></details>`;
   $('#mir-site-building').onchange=e=>{clear();buildingId=e.target.value;jobId='';history=[];render();};
   section.querySelectorAll('[data-site-view]').forEach(b=>b.onclick=()=>{active=b.dataset.siteView;section.querySelectorAll('[data-site-view]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.siteView===active)));renderView();});
   $('#mir-site-preview').onclick=async()=>{const button=$('#mir-site-preview');button.disabled=true;try{clear();snap=MIRStudioCotation.snapshot(state());const faces=MIRStudioCotation.fiveViews(snap,entry.planData.viewInventory);pdf=await MIRPDF.makePlan({faces,title:'MIR · '+snap.projectName+' · '+snap.buildingName,filename:'MIR-chantier-R'+snap.revision+'.pdf'});if(pdf.pages!==5)throw Error('Le PDF attend exactement cinq pages.');pdfURL=URL.createObjectURL(pdf.blob);$('#mir-site-download').href=pdfURL;$('#mir-site-download').download=pdf.filename;$('#mir-site-pdf').hidden=false;await openPDF(pdf.blob);$('#mir-site-message').textContent='Aperçu privé · '+pdf.pages+' pages · '+(snap.status==='draft'?'Brouillon avec réserves':'Dossier vérifié');$('#mir-site-attach').disabled=!jobId;}catch(e){$('#mir-site-message').textContent=e.message;}finally{button.disabled=false;}};
   for(const id of ['mir-site-revision','mir-site-notes','mir-site-validated'])$('#'+id).oninput=()=>{clear();$('#mir-site-pdf').hidden=true;$('#mir-site-attach').disabled=true;$('#mir-site-message').textContent='Les données ont changé. Régénérez l’aperçu.';};
   $('#mir-site-jobs-load').onclick=async()=>{try{jobs=await MIRStudioJobDocuments.jobs();const select=$('#mir-site-job-select');select.innerHTML='<option value="">Choisir une job</option>'+jobs.map(j=>`<option value="${esc(j.id)}">${esc(j.name)}</option>`).join('');$('#mir-site-message').textContent='Jobs autorisées chargées.';}catch(e){$('#mir-site-message').textContent=e.message;}};
   $('#mir-site-job-select').onchange=async e=>{jobId=e.target.value;clear();$('#mir-site-pdf').hidden=true;$('#mir-site-attach').disabled=true;history=[];if(!jobId||!buildingId)return;try{history=await MIRStudioJobDocuments.history(jobId,entry.id,buildingId);$('#mir-site-revision').value=history.length?Math.max(...history.map(x=>x.version))+1:1;renderHistory();$('#mir-site-message').textContent='Job choisie. Prévisualisez cette nouvelle révision.';}catch(e){jobId='';$('#mir-site-message').textContent=e.message;}};
   $('#mir-site-attach').onclick=async()=>{const button=$('#mir-site-attach');button.disabled=true;$('#mir-site-message').textContent='Rattachement en cours…';try{if(!snap||!pdf||!jobId)throw Error('Prévisualisez le dossier et choisissez sa job.');const latest=await MIRProjectStore.get(entry.id);if(JSON.stringify(latest.planData.viewInventory)!==JSON.stringify(entry.planData.viewInventory))throw Error('Le projet a changé. Actualisez la cotation avant de rattacher.');const current=history.find(x=>x.current),ack=await MIRStudioJobDocuments.attach({jobId,snapshot:snap,pdf,familyId:current?.familyId,expectedVersion:current?.version||0});history=ack.history;renderHistory();$('#mir-site-message').textContent='Rattachement confirmé par le serveur · révision '+ack.version+' · 5 pages.';}catch(e){$('#mir-site-message').textContent='Rattachement non confirmé : '+e.message;button.disabled=false;}};
   $('#mir-site-previous').onclick=()=>{if(previewPage>1){previewPage--;void drawPDF();}};$('#mir-site-next').onclick=()=>{if(pdfDocument&&previewPage<pdfDocument.numPages){previewPage++;void drawPDF();}};$('#mir-site-zoom-out').onclick=()=>{previewZoom=Math.max(.5,previewZoom/1.25);void drawPDF();};$('#mir-site-zoom-in').onclick=()=>{previewZoom=Math.min(3,previewZoom*1.25);void drawPDF();};
   renderView();renderHistory();
  }
  async function openPDF(blob){const P=await import('./vendor/pdfjs/pdf.min.mjs');P.GlobalWorkerOptions.workerSrc=new URL('vendor/pdfjs/pdf.worker.min.mjs',document.baseURI).href;const loading=P.getDocument({data:await blob.arrayBuffer()});pdfLoading=loading;const loadedDoc=await loading.promise;if(loading!==pdfLoading){await loading.destroy();return;}pdfDocument=loadedDoc;if(pdfDocument.numPages!==5)throw Error('Le PDF attend exactement cinq pages.');previewPage=1;previewZoom=1;await drawPDF();}
  async function drawPDF(){if(!pdfDocument)return;try{pdfTask?.cancel();const doc=pdfDocument,page=await doc.getPage(previewPage);if(doc!==pdfDocument)return;const canvas=$('#mir-site-pdf-canvas'),available=$('#mir-site-pdf-frame').clientWidth||800,viewport=page.getViewport({scale:1}),scale=available/viewport.width*previewZoom,ratio=Math.min(2,devicePixelRatio||1),size=page.getViewport({scale:scale*ratio});canvas.width=Math.ceil(size.width);canvas.height=Math.ceil(size.height);canvas.style.width=size.width/ratio+'px';canvas.style.height=size.height/ratio+'px';$('#mir-site-page-number').textContent=previewPage+' / 5 · '+Math.round(previewZoom*100)+' %';pdfTask=page.render({canvasContext:canvas.getContext('2d'),viewport:size});await pdfTask.promise;}catch(error){if(error.name!=='RenderingCancelledException')$('#mir-site-message').textContent='Aperçu à réessayer : '+error.message;}}
  function renderHistory(){if($('#mir-site-history'))$('#mir-site-history').innerHTML=history.map(h=>`<p>${esc(h.name)} · ${h.current?'Version courante':'Historique'} · ${h.pageCount} pages</p>`).join('');}
  function renderView(){const el=$('#mir-site-view');if(!buildingId){el.textContent='Choisissez le bâtiment à travailler.';return;}try{const s=MIRStudioCotation.snapshot(state()),faces=MIRStudioCotation.fiveViews(s,entry.planData.viewInventory),q=MIRStudioCotation.inputFor(entry.planData.viewInventory,buildingId,api.materials,api.settings());el.innerHTML=faces.find(f=>f.key===active).svg+`<p>${q.partial?'Quantités partielles':'Mesures vérifiées'} · ${q.result.pieces.length} coupes calculées par les règles MIR existantes.</p><details><summary>Calculs des murs et détails établis</summary><p>Surfaces : ${Number(q.result.areas.knownNetFt2||0).toFixed(2)} pi² connus${q.partial?' · total partiel':''}. Aucune addition avec les métrés historiques ci-dessous.</p><table><thead><tr><th>Profil</th><th>Longueur connue · pi</th><th>Coupes</th><th>État</th></tr></thead><tbody>${q.result.linearTotals.map(r=>`<tr><td>${esc(MIRTakeoff.profiles[r.profile]||r.profile)}</td><td>${Number(r.knownLengthFt||0).toFixed(2)}</td><td>${r.pieceCount}</td><td>${r.complete?'Calculé':'Partiel'}</td></tr>`).join('')}</tbody></table><p>Soffites : ${q.soffitAreaFt2==null?'À confirmer':Number(q.soffitAreaFt2).toFixed(2)+' pi² relevés'}. J : bords de mur / intérieurs seulement. Chutes, stocks et règles du dossier conservés, sans majoration ajoutée.</p>${[...new Set(q.result.warnings.map(w=>w.message))].slice(0,12).map(w=>`<p>${esc(w)}</p>`).join('')}</details>`;}catch(e){el.textContent=e.message;}}
  const focus=()=>{section.scrollIntoView({behavior:'smooth',block:'start'});$('#mir-site-building')?.focus({preventScroll:true});};if(document.querySelector('#export-five-site'))document.querySelector('#export-five-site').onclick=focus;root.MIR_SITE_COTATION={refresh,focus,snapshot:()=>snap,views:()=>snap?MIRStudioCotation.fiveViews(snap,entry.planData.viewInventory):null};void refresh();root.addEventListener('focus',()=>void refresh());return {refresh};
 }};
})(window);
